self.addEventListener("push",i=>{if(i.data)try{let t=i.data.json(),e=t.title||"SOLO E-Hailing Alert",n=t.role||"rider",o={body:t.body||"You have an active ride update.",icon:t.icon||("driver"===n?"/driver-icon-192.png":"/rider-icon-192.png"),badge:"/icon-192.png",vibrate:[200,100,200,100,300],tag:t.tag||"solo-notification",renotify:!0,requireInteraction:"driver"===n,data:{url:t.url||("driver"===n?"/driver":"/rider"),tripId:t.tripId,timestamp:Date.now()},actions:[{action:"open",title:"Open App"},{action:"dismiss",title:"Dismiss"}]};i.waitUntil(self.registration.showNotification(e,o))}catch(e){console.error("[ServiceWorker] Push error:",e);let t=i.data.text();i.waitUntil(self.registration.showNotification("SOLO Notification",{body:t,icon:"/icon-192.png"}))}}),self.addEventListener("notificationclick",i=>{if(i.notification.close(),"dismiss"===i.action)return;let t=(i.notification.data||{}).url||"/";i.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let e of i)if("focus"in e){e.focus(),"navigate"in e&&e.url!==t&&e.navigate(t);return}if(self.clients.openWindow)return self.clients.openWindow(t)}))});